const IGPU_USED = +(SLOTS.filter(s => !s.flm).reduce((a, s) => a + s.gb, 0) + 9.1).toFixed(1);
const FLM_USED = +SLOTS.filter(s => s.flm).reduce((a, s) => a + s.gb, 0).toFixed(1);

// ─── Throughput history (tok/s, combined across serving slots) ─────────
